type M = ReturnType<typeof input>;
const value = (bytes: string | null) =>
  bytes === null ? { kind: "ABSENT" } : { bytes, kind: "PRESENT" };
function context() {
  const dispositionInput = input(),
    disposition = {
      actionPlanDigest: c.computeModuleActionPlanDigest(dispositionInput.actionPlan),
      code: "decision.done",
      inputDigest: c.computeDispositionInputDigest(dispositionInput),
      outcome: { kind: "APPLY", operation: "PROJECT" },
      schemaVersion: "action-disposition/v1",
      subjectDigest: dispositionInput.actionPlan.actionCore.immutableSubjectDigest,
      subjectKind: "ACTION",
    };
  const request = {
    actionPlanDigest: c.computeModuleActionPlanDigest(dispositionInput.actionPlan),
    adapterConfigurationDigest: c.canonicalDigest(
      dispositionInput.moduleInput.adapterConfiguration,
    ),
    dispositionDigest: c.computeActionDispositionDigest(disposition),
    schemaVersion: "project-mutation-request/v1",
    sourceCycleId: dispositionInput.moduleInput.cycleRequest.cycleId,
    subjectDigest: disposition.subjectDigest,
    subjectKind: "ACTION",
    transactionId: id(20),
  };
  const effects = [
    { after: value("00ff"), before: value(null), kind: "COMPARE_REPLACE", resourceId: "a.create" },
    { after: value(null), before: value("aa"), kind: "COMPARE_REPLACE", resourceId: "b.remove" },
    { after: value("02"), before: value("01"), kind: "COMPARE_REPLACE", resourceId: "c.replace" },
  ];
  const observed = (
    n: number,
    values = effects.map((x) => x.before),
    at = `2026-08-31T01:00:0${n}.000Z`,
  ) => ({
    adapterConfigurationDigest: c.canonicalDigest(
      dispositionInput.moduleInput.adapterConfiguration,
    ),
    observationId: id(30 + n),
    observedAt: at,
    result: {
      kind: "COMPLETE",
      projectFacts: {
        ...copy(dispositionInput.moduleInput.projectFacts),
        observationId: id(40 + n),
        observedAt: at,
      },
      resources: effects.map((x, i) => ({ resourceId: x.resourceId, value: copy(values[i]) })),
    },
  });
  const dry = observed(1),
    before = observed(2),
    after = observed(
      3,
      effects.map((x) => x.after),
    );
  const intents = effects.map((_, i) => ({
      owner: "ADAPTER",
      resourceIdentityDigest: String(i + 1).repeat(64),
    })),
    plan = {
      observationDigest: c.computeProjectMutationObservationDigest(dry),
      outcome: { effects, kind: "PLANNED", resourceIntents: intents },
      requestDigest: c.computeProjectMutationRequestDigest(request),
      schemaVersion: "project-mutation-plan/v1",
      transactionId: request.transactionId,
    };
  const allocations = intents.map((x, i) => ({
    ...x,
    allocationId: id(50 + i),
    ownerTransactionId: request.transactionId,
    state: "ALLOCATED",
  }));
  const receipt = {
    afterObservationDigest: c.computeProjectMutationObservationDigest(after),
    beforeObservationDigest: c.computeProjectMutationObservationDigest(before),
    completedEffectCount: "3",
    outcome: { kind: "APPLIED" },
    phase: "AFTER_WRITE",
    planDigest: c.computeProjectMutationPlanDigest(plan),
    requestDigest: c.computeProjectMutationRequestDigest(request),
    resources: allocations,
    schemaVersion: "project-apply-receipt/v1",
    transactionId: request.transactionId,
  };
  return { dispositionInput, disposition, request, dry, before, after, plan, receipt };
}
const requestBind = (f: M, r: unknown = f.request) =>
  c.validateProjectMutationRequestBinding(f.dispositionInput, null, null, f.disposition, r);
const planBind = (f: M, o: unknown = f.dry, p: unknown = f.plan) =>
  c.validateProjectMutationPlanBinding(
    f.dispositionInput,
    null,
    null,
    f.disposition,
    f.request,
    o,
    p,
  );
const applyBind = (
  f: M,
  b: unknown = f.before,
  a: unknown = f.after,
  r: unknown = f.receipt,
  idValue: unknown = c.computeProjectMutationPlanDigest(f.plan),
) =>
  c.validateProjectApplyReceiptBinding(
    f.dispositionInput,
    null,
    null,
    f.disposition,
    f.request,
    f.dry,
    f.plan,
    idValue,
    b,
    a,
    r,
  );
const parsers = {
  "project-mutation-request/v1": c.parseProjectMutationRequest,
  "project-mutation-plan/v1": c.parseProjectMutationPlan,
  "project-apply-receipt/v1": c.parseProjectApplyReceipt,
};
const digests = {
  "project-mutation-request/v1": c.computeProjectMutationRequestDigest,
  "project-mutation-plan/v1": c.computeProjectMutationPlanDigest,
  "project-apply-receipt/v1": c.computeProjectApplyReceiptDigest,
};

test("pins every request, plan and receipt cell to independent bytes, full frames and hashes", () => {
  for (const golden of goldens) {
    const record = JSON.parse(golden.text),
      bytes = new TextEncoder().encode(golden.text);
    expect(parsers[golden.schema](record)).toEqual({ ok: true, value: record });
    expect(c.parseProjectMutationContract(golden.schema, record)).toEqual({
      ok: true,
      value: record,
    });
    expect(c.parseContract(golden.schema, record)).toEqual({ ok: true, value: record });
    expect(c.serializeContract(golden.schema, record)).toEqual({
      ok: true,
      bytes,
      digest: golden.digest,
    });
    expect(digests[golden.schema](record)).toBe(golden.digest);
    expect(
      Buffer.from(c.framedBytes(golden.schema, [c.frame.canonical(record)])).toString("hex"),
    ).toBe(golden.frameHex);
    expect(hash(Buffer.from(golden.frameHex, "hex"))).toBe(golden.digest);
    expect(hash(golden.text)).not.toBe(golden.digest);
    expect(c.parseCanonicalContractBytes(golden.schema, bytes)).toEqual({
      ok: true,
      value: record,
    });
    const shared = new Uint8Array(new SharedArrayBuffer(bytes.length));
    shared.set(bytes);
    expect(c.parseCanonicalContractBytes(golden.schema, shared).ok).toBe(false);
  }
  expect(c.projectMutationSchemaVersions).toEqual([
    "project-mutation-request/v1",
    "project-mutation-plan/v1",
    "project-apply-receipt/v1",
  ]);
  expect(c.parseProjectMutationContract("project-mutation/v1", {})).toBeNull();
});

test("value/effect/observation literals close every byte and source-state arm", () => {
  for (const row of [value(null), value(""), value("00ff")])
    expect(c.parseProjectMutationValue(row).ok).toBe(true);
  for (const row of [
    { kind: "PRESENT", bytes: "0" },
    { kind: "PRESENT", bytes: "GG" },
    { kind: "ABSENT", bytes: "" },
    { kind: "MISSING" },
    { kind: "PRESENT", bytes: "00".repeat(4097) },
  ])
    expect(c.parseProjectMutationValue(row).ok).toBe(false);
  expect(c.parseProjectMutationValue({ kind: "PRESENT", bytes: "00".repeat(4096) }).ok).toBe(true);
  for (const [before, after] of [
    [value(null), value("00")],
    [value("00"), value(null)],
    [value("00"), value("01")],
  ])
    expect(
      c.parseProjectMutationEffect({
        after,
        before,
        kind: "COMPARE_REPLACE",
        resourceId: "resource.one",
      }).ok,
    ).toBe(true);
  expect(
    c.parseProjectMutationEffect({
      after: value("00"),
      before: value("00"),
      kind: "COMPARE_REPLACE",
      resourceId: "resource.one",
    }).ok,
  ).toBe(false);
  const f = context();
  expect(c.parseProjectMutationObservation(f.dry).ok).toBe(true);
  expect(c.computeProjectMutationObservationDigest(f.dry)).toBe(hash(c.canonicalJson(f.dry)));
  for (const result of [
    { kind: "UNAVAILABLE", reason: "SOURCE_UNAVAILABLE" },
    { kind: "UNAVAILABLE", reason: "OBSERVATION_TIMEOUT" },
    { kind: "UNKNOWN", reason: "SOURCE_UNKNOWN" },
    { kind: "UNKNOWN", reason: "OBSERVATION_INVALID" },
  ])
    expect(c.parseProjectMutationObservation({ ...f.dry, result }).ok).toBe(true);
  for (const mutation of [
    (x: M) => x.result.resources.reverse(),
    (x: M) => x.result.resources.push(copy(x.result.resources[0])),
    (x: M) => (x.observationId = x.result.projectFacts.observationId),
    (x: M) => (x.result.projectFacts.state = "UNKNOWN"),
    (x: M) => (x.extra = true),
  ]) {
    const x = copy(f.dry);
    mutation(x);
    expect(c.parseProjectMutationObservation(x).ok).toBe(false);
  }
  for (const length of [0, 64]) {
    const x = copy(f.dry);
    x.result.resources = Array.from({ length }, (_, i) => ({
      resourceId: `resource.${String(i).padStart(3, "0")}`,
      value: value(null),
    }));
    expect(c.parseProjectMutationObservation(x).ok).toBe(true);
  }
  const too = copy(f.dry);
  too.result.resources = Array.from({ length: 65 }, (_, i) => ({
    resourceId: `resource.${String(i).padStart(3, "0")}`,
    value: value(null),
  }));
  expect(
    too.result.resources.every(
      (row: M, i: number) => i === 0 || too.result.resources[i - 1]!.resourceId < row.resourceId,
    ),
  ).toBe(true);
  expect(c.parseProjectMutationObservation(too).ok).toBe(false);
});

test("request binds only PROJECT apply, actual context, target, owner and captured bytes", () => {
  const f = context();
  expect(requestBind(f)).toEqual({ ok: true, value: f.request });
  expect(c.parseProjectMutationRequest({ ...f.request, subjectKind: "WORKER_RESULT" }).ok).toBe(
    true,
  );
  for (const field of [
    "actionPlanDigest",
    "adapterConfigurationDigest",
    "dispositionDigest",
    "subjectDigest",
  ]) {
    const r = copy(f.request);
    (r as Record<string, unknown>)[field] = "9".repeat(64);
    expect(requestBind(f, r).ok).toBe(false);
  }
  for (const field of ["sourceCycleId", "transactionId"]) {
    const r = copy(f.request);
    (r as Record<string, unknown>)[field] = id(99);
    expect(requestBind(f, r).ok).toBe(field === "transactionId");
  }
  for (const outcome of [
    { kind: "NO_ACTION" },
    { kind: "APPLY", operation: "PROMOTE" },
    { kind: "UNKNOWN", reason: "INPUT_UNPROVEN" },
  ]) {
    const disposition = { ...f.disposition, outcome };
    expect(
      c.validateProjectMutationRequestBinding(
        f.dispositionInput,
        null,
        null,
        disposition,
        f.request,
      ).ok,
    ).toBe(false);
  }
  const worker = context();
  expect(
    c.validateProjectMutationRequestBinding(
      worker.dispositionInput,
      new Uint8Array(),
      null,
      worker.disposition,
      worker.request,
    ).ok,
  ).toBe(false);
  const candidate = { ...f.request, subjectKind: "RELEASE_CANDIDATE" };
  expect(c.parseProjectMutationRequest(candidate).ok).toBe(false);
});

test("dry plan keeps observation null rules, source states and complete effect census distinct", () => {
  const f = context();
  expect(planBind(f)).toEqual({ ok: true, value: f.plan });
  const cases = [
    [null, { kind: "UNKNOWN", reason: "OBSERVATION_UNAVAILABLE" }, true],
    [{}, { kind: "UNKNOWN", reason: "OBSERVATION_INVALID" }, true],
    [f.dry, { kind: "UNKNOWN", reason: "OBSERVATION_INVALID" }, false],
    [
      { ...f.dry, result: { kind: "UNAVAILABLE", reason: "SOURCE_UNAVAILABLE" } },
      { kind: "UNKNOWN", reason: "SOURCE_UNAVAILABLE" },
      true,
    ],
    [
      { ...f.dry, result: { kind: "UNKNOWN", reason: "SOURCE_UNKNOWN" } },
      { kind: "UNKNOWN", reason: "SOURCE_UNKNOWN" },
      true,
    ],
    [f.dry, { kind: "UNKNOWN", reason: "ADMISSION_UNPROVEN" }, true],
  ];
  for (const [observation, outcome, ok] of cases as M[]) {
    const plan = {
      ...f.plan,
      observationDigest: outcome.reason?.startsWith("OBSERVATION_")
        ? null
        : c.computeProjectMutationObservationDigest(observation),
      outcome,
    };
    expect(planBind(f, observation, plan).ok).toBe(ok);
  }
  for (const [mutate, shapeOk] of [
    [(p: M) => (p.requestDigest = "9".repeat(64)), true],
    [(p: M) => (p.transactionId = id(99)), true],
    [(p: M) => (p.outcome.effects[0].before = value("ff")), true],
    [(p: M) => p.outcome.effects.reverse(), false],
    [(p: M) => (p.outcome.resourceIntents[0].owner = "HOST"), false],
  ] as const) {
    const p = copy(f.plan);
    mutate(p);
    expect(c.parseProjectMutationPlan(p).ok).toBe(shapeOk);
    expect(planBind(f, f.dry, p).ok).toBe(false);
  }
  const fewerIntents = copy(f.plan);
  fewerIntents.outcome.resourceIntents.pop();
  // Effect mapping and managed-intent completeness are separate owner claims at this boundary.
  expect(c.parseProjectMutationPlan(fewerIntents).ok).toBe(true);
  expect(planBind(f, f.dry, fewerIntents)).toEqual({ ok: true, value: fewerIntents });
  const empty = copy(f.plan);
  empty.outcome.effects = [];
  expect(c.parseProjectMutationPlan(empty).ok).toBe(false);
  for (const length of [1, 64]) {
    const p = copy(f.plan),
      o = copy(f.dry);
    p.outcome.effects = Array.from({ length }, (_, i) => ({
      after: value("00"),
      before: value(null),
      kind: "COMPARE_REPLACE",
      resourceId: `r.${String(i).padStart(3, "0")}`,
    }));
    p.outcome.resourceIntents = p.outcome.effects.map((_: M, i: number) => ({
      owner: "ADAPTER",
      resourceIdentityDigest: i.toString(16).padStart(64, "0"),
    }));
    o.result.resources = p.outcome.effects.map((x: M) => ({
      resourceId: x.resourceId,
      value: x.before,
    }));
    p.observationDigest = c.computeProjectMutationObservationDigest(o);
    expect(planBind(f, o, p).ok).toBe(true);
  }
  const overEffects = copy(f.plan);
  overEffects.outcome.effects = Array.from({ length: 65 }, (_, i) => ({
    after: value("00"),
    before: value(null),
    kind: "COMPARE_REPLACE",
    resourceId: `resource.${String(i).padStart(3, "0")}`,
  }));
  expect(overEffects.outcome.effects.every((row: M) => c.parseProjectMutationEffect(row).ok)).toBe(
    true,
  );
  expect(
    overEffects.outcome.effects.every(
      (row: M, i: number) =>
        i === 0 || overEffects.outcome.effects[i - 1]!.resourceId < row.resourceId,
    ),
  ).toBe(true);
  expect(c.parseProjectMutationPlan(overEffects).ok).toBe(false);
  const overIntents = copy(f.plan);
  overIntents.outcome.resourceIntents = Array.from({ length: 65 }, (_, i) => ({
    owner: "ADAPTER",
    resourceIdentityDigest: i.toString(16).padStart(64, "0"),
  }));
  expect(c.parseDispatchResourceIntents(overIntents.outcome.resourceIntents).ok).toBe(true);
  expect(c.parseProjectMutationPlan(overIntents).ok).toBe(false);
});

test("apply joins exact plan-id, transaction, allocations, ordered pre/postimages and progress", () => {
  const f = context();
  expect(applyBind(f)).toEqual({ ok: true, value: f.receipt });
  const shorterPlan = copy(f.plan);
  shorterPlan.outcome.resourceIntents.pop();
  expect(planBind(f, f.dry, shorterPlan)).toEqual({ ok: true, value: shorterPlan });
  const shorterReceipt = {
    ...copy(f.receipt),
    planDigest: c.computeProjectMutationPlanDigest(shorterPlan),
    resources: copy(f.receipt.resources.slice(0, 2)),
  };
  const bindShorter = (receipt: unknown) =>
    c.validateProjectApplyReceiptBinding(
      f.dispositionInput,
      null,
      null,
      f.disposition,
      f.request,
      f.dry,
      shorterPlan,
      c.computeProjectMutationPlanDigest(shorterPlan),
      f.before,
      f.after,
      receipt,
    );
  expect(bindShorter(shorterReceipt)).toEqual({ ok: true, value: shorterReceipt });
  for (const resources of [shorterReceipt.resources.slice(0, 1), copy(f.receipt.resources)]) {
    const mismatched = { ...shorterReceipt, resources };
    expect(c.parseProjectApplyReceipt(mismatched).ok).toBe(true);
    expect(bindShorter(mismatched).ok).toBe(false);
  }
  for (const field of ["planDigest", "requestDigest"]) {
    const r = copy(f.receipt);
    (r as Record<string, unknown>)[field] = "9".repeat(64);
    expect(applyBind(f, f.before, f.after, r).ok).toBe(false);
  }
  for (const value of [null, "9".repeat(64), {}, id(99)])
    expect(applyBind(f, f.before, f.after, f.receipt, value).ok).toBe(false);
  for (const field of ["transactionId", "ownerTransactionId", "resourceIdentityDigest"]) {
    const r = copy(f.receipt);
    if (field === "transactionId") r.transactionId = id(99);
    else
      (r.resources[0]! as Record<string, unknown>)[field] =
        field === "ownerTransactionId" ? id(99) : "9".repeat(64);
    expect(applyBind(f, f.before, f.after, r).ok).toBe(false);
  }
  for (const [before, after] of [
    [null, f.after],
    [f.before, null],
    [{ ...f.before, observationId: id(31) }, f.after],
    [f.before, { ...f.after, observedAt: "2026-08-31T00:59:00.000Z" }],
  ])
    expect(applyBind(f, before, after).ok).toBe(false);
  const moved = copy(f.before);
  moved.result.resources[0]!.value = value("ff");
  expect(applyBind(f, moved, f.after).ok).toBe(false);
  const wrong = copy(f.after);
  wrong.result.resources[2]!.value = value("03");
  expect(applyBind(f, f.before, wrong).ok).toBe(false);
  const refused = {
    ...f.receipt,
    afterObservationDigest: null,
    completedEffectCount: "0",
    outcome: { kind: "REFUSED", reason: "POLICY_REFUSED" },
    phase: "BEFORE_WRITE",
    resources: f.receipt.resources.map((x: M, i: number) => ({
      ...x,
      allocationId: i ? null : x.allocationId,
      state: i ? "NOT_ALLOCATED" : "ALLOCATED",
    })),
  };
  expect(applyBind(f, f.before, null, refused).ok).toBe(true);
  const precondition = {
    ...refused,
    outcome: { kind: "REFUSED", reason: "PRECONDITION_MOVED" },
    beforeObservationDigest: c.computeProjectMutationObservationDigest(moved),
  };
  expect(applyBind(f, moved, null, precondition).ok).toBe(true);
  expect(
    applyBind(f, f.before, null, {
      ...precondition,
      beforeObservationDigest: c.computeProjectMutationObservationDigest(f.before),
    }).ok,
  ).toBe(false);
  for (const phase of ["BEFORE_WRITE", "WRITING", "AFTER_WRITE"]) {
    const r = {
      ...f.receipt,
      afterObservationDigest: phase === "BEFORE_WRITE" ? null : f.receipt.afterObservationDigest,
      beforeObservationDigest: phase === "WRITING" ? null : f.receipt.beforeObservationDigest,
      completedEffectCount: phase === "BEFORE_WRITE" ? "0" : phase === "WRITING" ? "1" : "3",
      outcome: { kind: "UNKNOWN", reason: "WRITE_UNPROVEN" },
      phase,
      resources: f.receipt.resources.map((x: M, i: number) => ({
        ...x,
        allocationId: i === 2 ? null : x.allocationId,
        state: i === 2 ? "UNKNOWN" : "ALLOCATED",
      })),
    };
    expect(
      applyBind(
        f,
        phase === "WRITING" ? null : f.before,
        phase === "BEFORE_WRITE" ? null : f.after,
        r,
      ).ok,
    ).toBe(true);
  }
  for (const count of ["00", "-1", "65", "4"]) {
    const r = { ...f.receipt, completedEffectCount: count };
    expect(applyBind(f, f.before, f.after, r).ok).toBe(false);
  }
});

test("closed nested records and hostile inputs refuse without input code", () => {
  const f = context();
  for (const [parse, row, paths] of [
    [c.parseProjectMutationRequest, f.request, [[]]],
    [c.parseProjectMutationPlan, f.plan, [[], ["outcome"]]],
    [c.parseProjectApplyReceipt, f.receipt, [[], ["outcome"]]],
  ] as M[]) {
    for (const path of paths) {
      let pristine = row;
      for (const key of path) pristine = pristine[key];
      const extra = copy(row);
      let at = extra;
      for (const key of path) at = at[key];
      at.extra = true;
      expect(parse(extra).ok).toBe(false);
      for (const key of Object.keys(pristine)) {
        const missing = copy(row);
        let target = missing;
        for (const part of path) target = target[part];
        delete target[key];
        expect(parse(missing).ok).toBe(false);
      }
    }
  }
  let calls = 0;
  const hostile = [
    new Proxy(
      {},
      {
        ownKeys() {
          calls++;
          throw Error("trap");
        },
      },
    ),
    Object.defineProperty({}, "kind", {
      enumerable: true,
      get() {
        calls++;
        throw Error("getter");
      },
    }),
    {
      toJSON() {
        calls++;
        throw Error("json");
      },
    },
  ];
  for (const row of hostile)
    for (const parse of [
      c.parseProjectMutationValue,
      c.parseProjectMutationEffect,
      c.parseProjectMutationObservation,
      c.parseProjectMutationRequest,
      c.parseProjectMutationPlan,
      c.parseProjectApplyReceipt,
    ])
      expect(parse(row).ok).toBe(false);
  expect(
    c.validateProjectMutationRequestBinding(hostile[0], null, null, f.disposition, f.request).ok,
  ).toBe(false);
  expect(calls).toBe(0);
});
